sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // List of KPIs (use case, count, percentage)
    var kpis = [
        { "use_case": "Licensable Software Models", "count": 870, "percentage": 100 },
        { "use_case": "License Under Management", "count": 876, "percentage": 100 },
        { "use_case": "Software model without DMAP", "count": 133, "percentage": 100 },
        { "use_case": "Software model without downgrade rights", "count": 6, "percentage": 100 },
        { "use_case": "Software model without suite component defined", "count": 883, "percentage": 100 },
        { "use_case": "Software model which are suite component which has no inference percentage defined", "count": 179, "percentage": 100 },
        { "use_case": "Software model without product lifecycle", "count": 0, "percentage": 100 },
        { "use_case": "Non licensable software models", "count": 877, "percentage": 100 },
        { "use_case": "Software model without any subscriptions", "count": 883, "percentage": 100 },
        { "use_case": "Software model without entitlement", "count": 883, "percentage": 100 },
        { "use_case": "Software model with client access", "count": 0, "percentage": 100 },
        { "use_case": "Software model with metric attributes", "count": 3150, "percentage": 100 }
    ];

    // Loop through each KPI and create a task
    kpis.forEach(function(kpi) {
        var task = new GlideRecord('task'); // Replace with your task table name (e.g., 'incident' or 'task')
        task.initialize();
        task.short_description = 'Task for ' + kpi.use_case; // Task title
        task.description = 'This task is related to the KPI: ' + kpi.use_case + ' with count: ' + kpi.count;
        task.priority = 3; // Set priority as needed
        task.insert(); // Create the task record
    });

    // Send response back to the caller
    response.setStatus(200);
    response.setBody({ "message": "Tasks created successfully for all KPIs." });

})(request, response);
